    const phase = String(battery.phase || "").toUpperCase();
    if (!PHASES.includes(phase)) return;

    // Number(null) === 0, so an unavailable battery would otherwise be counted as a
    // real 0 W contribution and shift the phase's command limit.
    if (!isReading(battery.power)) return;
