/* Mode selection
 *
 * Peak shaving can be triggered by:
 * - Grid power exceeds the import/export limit set by the user
 * - Optional per-phase power exceeds the configured phase limit
 *
 * Per-phase protection only runs when enabled, L1/L2/L3 sensors are readable,
 * and the overloaded phase has at least one assigned battery.
 *
 * The shaving direction and target are latched at the moment of the real
 * violation and held for the release timeout: the battery response can flip
 * P1 import/export, but that must not turn an import shave into an export
 * shave or vice versa.
 */

// Timestamp
const now = Date.now();

// Logger
const log = global.get("logger");

// Configuration & State recovery
const PEAK_SHAVING_TIMEOUT_SEC = 10;
let isPeakShaving = flow.get("is_peak_shaving") ?? false;
let lastPowerLimitViolation = flow.get("last_power_limit_violation") ?? now;
let isPowerLimitViolation = false;
let peakDirection = flow.get("peak_shave_direction") || null;
let powerLimit = Number(flow.get("peak_shave_power_limit")) || 0;

// Helpers
const PHASES = ["L1", "L2", "L3"];
const toNumberOrNull = (value) => {
    const numericValue = Number(value);
    return Number.isFinite(numericValue) ? numericValue : null;
};
const sumValues = (values) => values.reduce((sum, value) => sum + value, 0);

// Input data | grid
const P1_power = toNumberOrNull(RED.util.getMessageProperty(msg, "grid_power")) ?? 0;
// Input data | Charge PV
const hasImportLimit = RED.util.getMessageProperty(msg, "grid_power_has_limit_import") || false;
const importLimit = toNumberOrNull(RED.util.getMessageProperty(msg, "grid_power_limit_import")) ?? 0;
// Input data | Sell PV
const hasExportLimit = RED.util.getMessageProperty(msg, "grid_power_has_limit_export") || false;
const exportLimit = toNumberOrNull(RED.util.getMessageProperty(msg, "grid_power_limit_export")) ?? 0;

// Input data | phase protection
const phaseProtection = RED.util.getMessageProperty(msg, "phase_protection") || {};
const phaseProtectionEnabled = phaseProtection.enabled === true;
const phasePower = RED.util.getMessageProperty(msg, "grid_power_phase") || {};
const phaseLimit = toNumberOrNull(RED.util.getMessageProperty(msg, "grid_power_limit_phase"));
const batteries = Array.isArray(msg.batteries) ? msg.batteries : [];
const assignedPhases = new Set(
    batteries
        .map((battery) => String(battery.phase || "").toUpperCase())
        .filter((phase) => PHASES.includes(phase))
);
const phaseReadings = PHASES.reduce((result, phase) => {
    result[phase] = toNumberOrNull(phasePower[phase] ?? phasePower[phase.toLowerCase()]);
    return result;
}, {});
const phaseSensorsAvailable = PHASES.every((phase) => phaseReadings[phase] !== null);
const phaseBatteryPower = RED.util.getMessageProperty(msg, "phase_protection.phase_battery_power") || {};
const phaseBatteryChargePower = phaseBatteryPower.charge || {};
const phaseBatteryDischargePower = phaseBatteryPower.discharge || {};
const phaseLimitAvailable = phaseLimit !== null && phaseLimit > 0;
const phaseAssignmentsAvailable = assignedPhases.size > 0;
const phaseProtectionAvailable = phaseProtectionEnabled && phaseSensorsAvailable && phaseLimitAvailable && phaseAssignmentsAvailable;

const phaseState = {
    enabled: phaseProtectionEnabled,
    available: phaseProtectionAvailable,
    active: false,
    direction: null,
    limit: phaseLimitAvailable ? phaseLimit : null,
    sensors_available: phaseSensorsAvailable,
    assignments_available: phaseAssignmentsAvailable,
    assigned_phases: [...assignedPhases],
    active_phases: [],
    required_by_phase: { L1: 0, L2: 0, L3: 0 },
    required_phase_power: 0,
    aggregate_required_power: 0,
    aggregate_residual_power: 0,
    required_total_power: 0,
    target_grid_consumption_in_w: null,
    unassigned_violations: [],
};

function getPhaseRequirements(direction) {
    const requiredByPhase = { L1: 0, L2: 0, L3: 0 };
    const unassignedViolations = [];

    if (!phaseProtectionAvailable) {
        return { requiredByPhase, activePhases: [], unassignedViolations };
    }

    PHASES.forEach((phase) => {
        const reading = phaseReadings[phase];
        const currentChargePower = direction === "import"
            ? (toNumberOrNull(phaseBatteryChargePower[phase]) ?? 0)
            : 0;
        const currentDischargePower = direction === "export"
            ? (toNumberOrNull(phaseBatteryDischargePower[phase]) ?? 0)
            : 0;
        const excess = direction === "import"
            ? reading - currentChargePower - phaseLimit
            : (reading * -1) - currentDischargePower - phaseLimit;

        if (excess <= 0) return;

        const requiredPower = Math.ceil(excess);
        if (assignedPhases.has(phase)) {
            requiredByPhase[phase] = requiredPower;
        } else {
            unassignedViolations.push({ phase, direction, required_power: requiredPower, power: reading });
        }
    });

    return {
        requiredByPhase,
        activePhases: PHASES.filter((phase) => requiredByPhase[phase] > 0),
        unassignedViolations,
    };
}

const aggregateImportRequired = hasImportLimit && importLimit > 0
    ? Math.max(0, P1_power - importLimit)
    : 0;
// Preserve the existing aggregate export activation behavior for backward compatibility.
const aggregateExportViolation = hasExportLimit && P1_power < exportLimit;
const aggregateExportRequired = hasExportLimit && exportLimit > 0
    ? Math.max(0, (P1_power * -1) - exportLimit)
    : 0;

const importPhase = getPhaseRequirements("import");
const exportPhase = getPhaseRequirements("export");
const importPhaseRequired = sumValues(Object.values(importPhase.requiredByPhase));
const exportPhaseRequired = sumValues(Object.values(exportPhase.requiredByPhase));

let selectedDirection = null;
let selectedTarget = null;
let selectedPhase = null;
let selectedAggregateRequired = 0;

// Import protection is prioritized when there is a conflict because it protects loads drawing from the grid.
// Aggregate import/export violations still depend on their own toggles, but
// phase-only violations are controlled by the per-phase protection toggle.
if (aggregateImportRequired > 0 || importPhaseRequired > 0) {
    selectedDirection = "import";
    selectedPhase = importPhase;
    selectedAggregateRequired = aggregateImportRequired;
    const requiredTotal = Math.max(aggregateImportRequired, importPhaseRequired);
    selectedTarget = P1_power - requiredTotal;
} else if (exportPhaseRequired > 0) {
    selectedDirection = "export";
    selectedPhase = exportPhase;
    selectedAggregateRequired = aggregateExportRequired;
    const requiredTotal = Math.max(aggregateExportRequired, exportPhaseRequired);
    selectedTarget = P1_power + requiredTotal;
} else if (aggregateExportViolation) {
    selectedDirection = P1_power > 0 ? "import" : "export";
    selectedTarget = P1_power > 0 ? importLimit : exportLimit;
}

if (selectedDirection !== null) {
    isPeakShaving = true;
    isPowerLimitViolation = true;
    // Latch direction and target for the duration of the release timeout.
    peakDirection = selectedDirection;
    powerLimit = selectedTarget ?? (P1_power > 0 ? importLimit : exportLimit);
}

if (selectedPhase && sumValues(Object.values(selectedPhase.requiredByPhase)) > 0) {
    const phaseRequired = sumValues(Object.values(selectedPhase.requiredByPhase));
    const requiredTotal = Math.max(selectedAggregateRequired, phaseRequired);

    phaseState.active = true;
    phaseState.direction = selectedDirection;
    phaseState.active_phases = selectedPhase.activePhases;
    phaseState.required_by_phase = selectedPhase.requiredByPhase;
    phaseState.required_phase_power = phaseRequired;
    phaseState.aggregate_required_power = selectedAggregateRequired;
    phaseState.aggregate_residual_power = Math.max(0, requiredTotal - phaseRequired);
    phaseState.required_total_power = requiredTotal;
    phaseState.target_grid_consumption_in_w = selectedTarget;
    phaseState.unassigned_violations = selectedPhase.unassignedViolations;

    log(this, `**Per-phase peak shaving** ${selectedDirection}: ${phaseState.active_phases.join(", ")} requires ${phaseRequired} W`);
}

if (phaseProtectionAvailable && importPhase.unassignedViolations.length > 0) {
    log(this, `Per-phase import violation without assigned battery: ${JSON.stringify(importPhase.unassignedViolations)}`, "warn");
}
if (phaseProtectionAvailable && exportPhase.unassignedViolations.length > 0) {
    log(this, `Per-phase export violation without assigned battery: ${JSON.stringify(exportPhase.unassignedViolations)}`, "warn");
}

// UPDATE timer or continue
if (isPowerLimitViolation) lastPowerLimitViolation = now;

// CALCULATE release logic
// Seconds since the last time the power limit was exceeded
let secondsSinceLastViolation = Math.floor((now - lastPowerLimitViolation) / 1000);

// RELEASE shaving logic
// Only release if we are currently shaving AND the timeout has passed
if (isPeakShaving && (secondsSinceLastViolation >= PEAK_SHAVING_TIMEOUT_SEC)) {
    isPeakShaving = false;
    peakDirection = null;
    powerLimit = 0;
    log(this,"Peak Shaving released, resume normal operation");
}

// UI & OUTPUT Logic
if (isPeakShaving) {
    // Timeout progress
    const secondsRemaining = PEAK_SHAVING_TIMEOUT_SEC - secondsSinceLastViolation;
    // Set latched grid power target
    msg.payload = powerLimit;
    // UI
    node.status({
        fill: "yellow",
        shape: "dot",
        text: isPowerLimitViolation
            ? (phaseState.active ? `Phase peak shaving` : `Peak Shaving`)
            : `Peak Shaving: release in ${secondsRemaining}s`
    });
} else {
    // UI
    node.status({
        fill: "green",
        shape: "dot",
        text: `Grid OK - ${msg.target}`
    });
}

// Persist state for next run
flow.set("is_peak_shaving", isPeakShaving);
flow.set("peak_shave_direction", peakDirection);
flow.set("peak_shave_power_limit", powerLimit);
if (isPowerLimitViolation) flow.set("last_power_limit_violation", now); // Power limit exceeded. Update the lastPowerLimitViolation timestamp to current time

// Finalize msg
RED.util.setMessageProperty(msg, "phase_protection", phaseState, true);
RED.util.setMessageProperty(msg, "strategy.is_peak_shaving", isPeakShaving, true);
RED.util.setMessageProperty(msg, "strategy.peak_direction", peakDirection, true);

// OUTPUT
return msg;

// Logger
const log = global.get("logger");

// Explain
log(this,`**Peak shaving mode** postponing '${msg.target}' strategy`);
node.status({ fill: "green", shape: "dot", text: `postponing '${msg.target}' strategy`});

// Original target
const ORIGINAL_TARGET = msg.target;

// Use the PID controller strategy
msg.target = "Self-consumption";
// Set the grid power limit
