        direction: phaseProtection.direction,
        active_phases: phaseProtection.active_phases || [],
        required_by_phase: phaseProtection.required_by_phase || {},
        required_phase_power: phaseProtection.required_phase_power || 0,
        aggregate_residual_power: phaseProtection.aggregate_residual_power || 0,
