if(Math.abs(P1_error) < P1_deadband) {
    // stop processing
    node.status({fill:"yellow",shape:"dot",text:`Halt, ${Math.round(Math.abs(P1_error))} W`});
    log(this, `**Stopped processing** 🌿power saving, ${Math.round(Math.abs(P1_error))} W is within deadband of ${P1_deadband} W`);
    msg.payload = 'halted by deadband';
    return msg;
} 

// Outside deadband
node.status({fill:"green",shape:"dot",text:`Pass, ${Math.round(Math.abs(P1_error))} W`});
return msg;

// Logger
var logdata = ""; // deprecated
const log = global.get("logger");

// Timing
let time_last = context.get('time_last') || Date.now(); // Milliseconds
let time_current = Date.now(); // Milliseconds
let time_delta = (time_current - time_last) / 1000; // Convert to seconds
// note: due to inherent 1 sec intervals of P1 meter we omit dt terms. This is mostly for bug checking and optimizations.

// Batteries
var B_power = msg.batteries_total_power; // charging is positive, discharging negative
var anti_windup_threshold = Number(flow.get("batteries_total_assignable_power")) || 0; // max available charge/discharge power.

// Process Variable (PV) currently measured grid power, Setpoint (SP) desired grid power, set 0 for NoM
var P1_power = msg.grid_power; // PV: consume is positive, supply to grid is negative
var P1_setpoint = flow.get("house_target_grid_consumption_in_w"); // SP: target value
var P1_error = msg.grid_error;  // W (watt), error signal = SP - PV
var P1_derivative = msg.grid_derivative; // Derivative of PV, not the error

// PID values
var Kp = flow.get("house_battery_control_kp") || 0.75;  // Proportional gain
var Ki = flow.get("house_battery_control_ki") || 0;     // Integral gain        Ki = Kp/Ti
var Kd = flow.get("house_battery_control_kd") || 0;     // Derivative gain      Kd = Kp*Td

// helpers
var I_integral_sum = flow.get('I_integral_sum') || 0;
var Gm = flow.get("master_gain")||1; // gain scheduling

// optimizations
var hysteresis = flow.get("house_battery_control_hysteresis_in_w"); // W (watt)

// advanced settings
const isDischargeDisabled = RED.util.getMessageProperty(msg,"advanced_settings.discharge_disabled");
const isChargeDisabled = RED.util.getMessageProperty(msg,"advanced_settings.charge_disabled");

// -- PID regulator --
// Proportional term
let p_term = Gm * Kp * P1_error;

// Integral term
let integral_max = 0;
if (Ki > 0) {
    // Integral term | integrate
    I_integral_sum += P1_error; 
    // Integral term | apply anti-windup
    integral_max = anti_windup_threshold / Ki; // the anti-windup value is set to the current controlable range of the batteries, given by the previous load balancer calculations
    I_integral_sum = Math.min(Math.max(I_integral_sum, -integral_max), integral_max);
} else {
    // If Ki is 0, keep everything 0
    I_integral_sum = 0;
    integral_max = 0;
}

// Integral term | the term
let i_term = Ki * I_integral_sum;

// Integral term | explain
logdata += `anti_windup_threshold=${anti_windup_threshold}, integral_max=${integral_max}| `; // deprecated

// Differential term
let d_term = Gm * Kd * (-P1_derivative); // omitted '/time_delta'. inherent P1 refresh fequency.

// Total PID output
var PID_output = p_term + i_term + d_term; // W (watt), the control input for the battery packs

// Charging or Discharging states
var B_was_charging = context.get("batteries_charging_last") || false;
var B_is_charging = PID_output > 0 ? true : false;

// Explain
logdata += `U(${time_delta}s)[${PID_output}] = P(${Kp})[${p_term}] + I(${Ki})[${i_term}] + D(${Kd})[${d_term}] | `; // deprecated
log(this,`**PID Controller**`);
log(this,`Step size: ${time_delta} s`);
if(Kp == 0 && Ki == 0 && Kd == 0) {
    log(this, `<font color="orange">**Controller disabled**</font> All PID gains are 0. Choose a PID preset or set gains > 0.`,"warn");
} else {
    // log(this, `P-term: ${Math.floor(p_term)} W @ P-gain ${Kp}`);
    // log(this, `I-term: ${Math.floor(i_term)} W @ I-gain ${Ki} (max. ${anti_windup_threshold} W)`);
    // log(this, `D-term: ${Math.floor(d_term)} W @ D-gain ${Kd}`);
    log(this, `**P** ${Math.floor(p_term)} W @ gain ${Kp}<br>**I** ${Math.floor(i_term)} W @ gain ${Ki} (max. ${anti_windup_threshold} W)<br>**D** ${Math.floor(d_term)} W @ gain ${Kd}`);
    log(this, `**PID ${B_is_charging ? 'Charge' : 'Discharge'}:** ${Math.floor(p_term)} + ${Math.floor(i_term)} + ${Math.floor(d_term)} = **${Math.round(PID_output)} Watt**`);
}

// Only one of the advanced settings below can be active at once.
// Advanced setting | discharge disabled
if(isDischargeDisabled && !B_is_charging) {
    // log explain
    logdata += `Discharging disabled, PID unwound U(${time_delta})[0]=0+0+0 | `;
    log(this,'**PID capped at 0**. Discharge is disabled in this strategy'); // via `msg.advanced_settings`
    // Set all PID terms to 0 and unwind integral sum
    PID_output = 0;
    p_term = 0;
    i_term = 0;
    d_term = 0;
    I_integral_sum = 0; // unwind
    // maintain charge scenario
    B_is_charging = true;

// Advanced setting | charge disabled
} else if (isChargeDisabled && B_is_charging) {
    // log explain
    logdata += `Charging disabled, PID unwound U(${time_delta})[0]=0+0+0 | `;
    log(this,'**PID capped at 0**. Charge is disabled in this strategy'); // via `msg.advanced_settings`
    // Set all PID terms to 0 and unwind integral sum
    PID_output = 0;
    p_term = 0;
    i_term = 0;
    d_term = 0;
    I_integral_sum = 0; // unwind
    // maintain discharge scenario
    B_is_charging = false;

// Advanced setting | hysteresis
} else if 
// prevents excessive switching between (dis)charge mode around the zero point.
// if new PID_output lies within hysteresis, it will not switch charge mode. 
// set hysteresis to 0, to apply no hysteresis
(B_is_charging !== B_was_charging && Math.abs(PID_output) < hysteresis){
    // log explain
    logdata += `Hysteresis prevented charge mode switch from ${B_was_charging ? "charging" : "discharging"} to ${B_is_charging ? "charging" : "discharging"} as ${Math.abs(PID_output)}W <= ${hysteresis}(hyst) | `;
    log(this,`Hysteresis prevented charge mode switch from ${B_was_charging ? "charging" : "discharging"} to ${B_is_charging ? "charging" : "discharging"} as ${Math.abs(PID_output)}W <= ${hysteresis}(hyst)`);
    // prevent negative charging or positive discharging values (not allowed)
    PID_output = (PID_output < 0 && B_is_charging) || ((PID_output > 0 && !B_is_charging)) ? 0 : PID_output;
    // maintain previous scenario
    B_is_charging = B_was_charging;
} 

// save for next iteration
context.set("batteries_charging_last", B_is_charging); //boolean

// OUTFLOW
context.set("time_last", Date.now());
flow.set("I_integral_sum", I_integral_sum);

// OUTPUT
RED.util.setMessageProperty(msg, "batteries_charging", B_is_charging, true);
RED.util.setMessageProperty(msg, "I_integral_sum", I_integral_sum,true);
msg.payload = Number(PID_output);

return [msg, // payload = PID_output
        { payload: Math.round(Number(P1_error))},
        { payload: Math.round(parseFloat(p_term))},
        { payload: Math.round(parseFloat(i_term))},
        { payload: Math.round(parseFloat(d_term))},
        { payload: B_is_charging},
        { payload: logdata }];

// INPUT
let PID_unfiltered = msg.payload; // W Watt
let PID_last = context.get("PID_last")||0; // W watt
let PID_damp = Number(flow.get("house_battery_control_pid_output_dampening"))||0; // 0% - 100%
PID_damp = PID_damp/100; // to Number

// simple averaging filter
let PID_filtered = (1-PID_damp)*PID_unfiltered + (PID_damp)*PID_last;

// Phase protection is a safety-oriented peak-shave path. Do not let output
// dampening reduce the correction below the immediate phase requirement.
const phaseProtection = RED.util.getMessageProperty(msg, "phase_protection") || {};
const phaseRequired = Number(phaseProtection.required_total_power) || 0;
if (phaseProtection.active === true && phaseRequired > 0) {
    if (phaseProtection.direction === "import" && PID_filtered > -phaseRequired) {
        PID_filtered = -phaseRequired;
    } else if (phaseProtection.direction === "export" && PID_filtered < phaseRequired) {
        PID_filtered = phaseRequired;
    }
}

// OUTFLOW
context.set("PID_last", PID_filtered);

// OUTPUT
msg.payload = Number(PID_filtered)
return msg;

// INFLOW
let maxCharge = msg.batteries_max_charge_power||undefined;
let maxDischarge = msg.batteries_max_discharge_power||undefined;
let isCharging = msg.batteries_charging||undefined;
let PID_output = msg.payload; // Watt

// No failsafe
if (maxCharge === undefined || maxDischarge == undefined) {
    node.status({ fill: "red", shape: "dot", text: "disabled" });
    node.warn(`Output Failsafe is INACTIVE. Max charge or discharge limits are undefined`);
    // continue without safeguard
    return msg;
} 

// limit
let limit = 0;

// charging state unknown
if(isCharging === undefined) {
    // limit on lowest of charge / discharge
    limit = Math.min(maxCharge,maxDischarge);    
}
// charging state known
limit = isCharging ? maxCharge : maxDischarge;

// Safe output
if (PID_output <= limit){
    node.status({ fill: "green", shape: "dot", text: "safe" });
    msg.payload = Math.round(msg.payload);
    return msg;
} 

// Unsafe, limit output
node.status({ fill: "yellow", shape: "ring", text: "power limiting" });
msg.payload = Math.round(Number(limit));
return msg;

// Logger
const log = global.get("logger");
log(this,"**PID load distribution**");

// INPUT
var batteries = Array.isArray(msg.batteries) ? msg.batteries : []; // Battery configuration as provided by `Home Batteries IO` flow
var isCharging = msg.batteries_charging; // Are we in a battery charging scenario?
var hasChargingLimiter = flow.get("has_soc_charging_limiter") || false; // Battery life improvement
var hasReverseDischargePriority = RED.util.getMessageProperty(msg, "advanced_settings.reverse_discharge_priority") ?? false; // Prioritize (dis)charging the same battery
const isDischargeDisabled = RED.util.getMessageProperty(msg,"advanced_settings.discharge_disabled"); // Disallow discharging?
const isChargeDisabled = RED.util.getMessageProperty(msg,"advanced_settings.charge_disabled"); // Disallow charging?
const phaseProtection = RED.util.getMessageProperty(msg, "phase_protection") || {};
const phaseProtectionActive = phaseProtection.active === true && ["import", "export"].includes(phaseProtection.direction);
const phaseDirectionMatches = (phaseProtection.direction === "import" && !isCharging) || (phaseProtection.direction === "export" && isCharging);
const phaseRequirements = phaseProtection.required_by_phase || {};
const phaseAggregateResidual = Math.max(0, Number(phaseProtection.aggregate_residual_power) || 0);
const phaseCommandLimits = RED.util.getMessageProperty(msg, "phase_protection.command_limit_by_phase") || {};
const phaseCommandLimitRemaining = {
    charge: { ...(phaseCommandLimits.charge || {}) },
    discharge: { ...(phaseCommandLimits.discharge || {}) },
};
const phaseAllocator = global.get("phasePowerAllocator") || {};
const PHASES = Array.isArray(phaseAllocator.phases) ? phaseAllocator.phases : ["L1", "L2", "L3"];
const usePhaseAllocator = RED.util.getMessageProperty(msg, "phase_protection.command_limits_available") === true;
const usePhaseWaterFill = usePhaseAllocator && !isCharging && typeof phaseAllocator.allocateWaterFill === "function";
const usePhasePriorityFirst = usePhaseAllocator && isCharging && typeof phaseAllocator.allocatePriorityWaterFill === "function";

// how much power do the batteries need to compensate?
const unassigned_power_initial = Math.round(Math.abs(msg.payload)); // Power in W to compensate using batteries
let remaining_output_power = unassigned_power_initial;
log(this,`How much power do the batteries need to compensate: ${unassigned_power_initial} W`);

// inits
var batteries_total_assignable_power = 0; // Current max. available total (dis)charge power. Exceeding this max should trigger the anti-windup routine for the Integral terms
const phaseAssignment = { L1: { required: 0, assigned: 0, unassigned: 0 }, L2: { required: 0, assigned: 0, unassigned: 0 }, L3: { required: 0, assigned: 0, unassigned: 0 } };
let aggregateAssignedPower = 0;

// enums
const CMODE = {
    STOP: "stop", // Marstek batteries disconnect a relay when this is set or Power is 0W
    CHARGE: "charge",
    DISCHARGE: "discharge"
}

/**
** Battery life improvement (slow charge near max SoC)
* @param {number} soc
* @param {number} max_power
*/
function chargingLimiter(soc, max_power) {
    // Must be greater than zero
    let limitedPower = Math.max(0, Number(max_power) || 0);

    // Limit charge at high SoC
    if (hasChargingLimiter) {
        if (soc >= 99)      limitedPower = Math.min(1000, limitedPower);
        else if (soc >= 95) limitedPower = Math.min(1500, limitedPower);
    }
    return limitedPower;
}

/**
* battery life improvement (disconnects battery only if the battery is not used for ... seconds)
* @param {string | number} batteryID
* @returns {{id: string|number, mode: string, power: number}} battery solution
*/
function getStopSolution(batteryID) {
    // idle time, before stop is given to inverter relay.
    let time_idle_minimum = flow.get("idle_time_minutes")*60*1000||0; // Milliseconds

    // retrieve last registered active times for each battery based on their ids
    let lasttime_active = context.get("lasttime_active") || [];

    // battery exists in register
    if(lasttime_active[batteryID] !== undefined){
        // timing
        let time_last = lasttime_active[batteryID]; // Milliseconds
        let time_now = Date.now();                  // Milliseconds
        let time_idle = (time_now - time_last); // Milliseconds

        // battery is ready for STOP
        if (time_idle >= time_idle_minimum) {
            log(this,`Battery ${batteryID} [STOP]: 0 Watt and disconnect relay.`);
            return {id: batteryID, mode: CMODE.STOP, power:0}; // STOP or 0 Watt disconnects relay
        }

        // battery is kept IDLE, while awaiting minimum inactive time
        log(this,`Battery ${batteryID} [IDLE]: 1 Watt for ${Math.round((time_idle_minimum-time_idle)/1000)}s. Keep relay engaged.`);
        return { id: batteryID, mode: isCharging ? CMODE.CHARGE : CMODE.DISCHARGE, power: 1 }; // 1 Watt keeps battery IDLE, keeping relay engaged
    }

    // battery missing in register
    log(this,`Battery ${batteryID} [IDLE]: unknown last active time`);
    return getActiveSolution(batteryID, 1); // set a last active time and engage idle state
}

/**
* Get battery solution and register a last active time.
* @param {any} batteryID
* @param {number} assigned_power
* @returns {{id: string|number, mode: string, power: number}} battery solution
*/
function getActiveSolution(batteryID, assigned_power){
    // register battery as active
    let lasttime_active = context.get("lasttime_active")||[]; // last registered active times for each battery based on their ids
    lasttime_active[batteryID] = Date.now();
    context.set("lasttime_active", lasttime_active);

    // solution
    return {
        id: batteryID,
        mode: isCharging ? CMODE.CHARGE : CMODE.DISCHARGE,
        power: Math.round(assigned_power)
    };
}

function getPhase(battery) {
    if (typeof phaseAllocator.getPhase === "function") return phaseAllocator.getPhase(battery);
    const phase = String(battery.phase || "").toUpperCase();
    return PHASES.includes(phase) ? phase : "unassigned";
}

// A phase limit of null means "no per-phase limit is known" - which is what
// `Phase command limits` publishes whenever per-phase peak shaving is off. It must not
// read as a 0 W ceiling, or every phase-assigned battery would be pinned at 0 W.
function getPhaseCommandLimitValue(phase) {
    if (!PHASES.includes(phase)) return Infinity;

    const direction = isCharging ? "charge" : "discharge";
    const value = phaseCommandLimits[direction]?.[phase];
    return isFiniteNumber(value) ? Math.max(0, Number(value)) : Infinity;
}

function getPhaseCommandLimitRemaining(phase) {
    if (!PHASES.includes(phase)) return Infinity;

    const direction = isCharging ? "charge" : "discharge";
    const value = phaseCommandLimitRemaining[direction]?.[phase];
    return isFiniteNumber(value) ? Math.max(0, Number(value)) : Infinity;
}

function usePhaseCommandLimit(phase, assignedPower) {
    if (!PHASES.includes(phase) || assignedPower <= 0) return;

    const direction = isCharging ? "charge" : "discharge";
    const value = phaseCommandLimitRemaining[direction]?.[phase];
    if (!isFiniteNumber(value)) return;

    phaseCommandLimitRemaining[direction][phase] = Math.max(0, Number(value) - assignedPower);
}

function isFiniteNumber(value) {
    // Number(null) === Number("") === 0, so an unavailable reading would otherwise
    // pass as a real 0 and the battery would never be skipped.
    if (value === null || value === undefined || value === "") return false;
    return Number.isFinite(Number(value));
}

function getUnavailableFields(battery) {
    const unavailableFields = [];
    const socLimitName = isCharging ? "max SoC" : "min SoC";
    const socLimit = isCharging ? battery.soc_max : battery.soc_min;
    const powerLimitName = isCharging ? "max charge power" : "max discharge power";
    const powerLimit = isCharging ? battery.charging_max : battery.discharging_max;

    if (!isFiniteNumber(battery.soc)) unavailableFields.push("SoC");
    if (!isFiniteNumber(socLimit)) unavailableFields.push(socLimitName);
    if (!isFiniteNumber(powerLimit)) unavailableFields.push(powerLimitName);

    return unavailableFields;
}

function getSkipReason(battery) {
    if (battery.rs485 !== "enable") {
        return `Battery ${battery.id} [SKIP]: skipped because RS485 is not 'enable'`;
    }

    const unavailableFields = getUnavailableFields(battery);
    if (unavailableFields.length > 0) {
        return `Battery ${battery.id} [SKIP]: skipped because required telemetry is unavailable: ${unavailableFields.join(", ")}`;
    }

    if (isCharging && battery.soc >= battery.soc_max) {
        return `Battery ${battery.id} [SKIP]: skipped because SoC (${battery.soc}%) >= Max (${battery.soc_max}%) while charging`;
    }
    if (!isCharging && battery.soc <= battery.soc_min) {
        return `Battery ${battery.id} [SKIP]: skipped because SoC (${battery.soc}%) <= Min (${battery.soc_min}%) while discharging`;
    }
    if (!isCharging && isDischargeDisabled) {
        return `Battery ${battery.id} [SKIP]: skipped, discharging was disabled via msg property`;
    }
    if (isCharging && isChargeDisabled) {
        return `Battery ${battery.id} [SKIP]: skipped, charging was disabled via msg property`;
    }
    return null;
}

// -- BATTERY DISCHARGE PRIORITY
if (!isCharging && hasReverseDischargePriority) {
   batteries.reverse();
}

const phaseAssignablePower = { L1: 0, L2: 0, L3: 0, unassigned: 0 };

const batteryStates = batteries.map((battery) => {
    // Explain
    log(this, `Battery ${battery.id}: ${battery.soc}% (min: ${battery.soc_min}%, max: ${battery.soc_max}%) ; Phase: ${getPhase(battery)} ; RS485: ${battery.rs485=='enable'?'OK':'Nok'}`);

    const phase = getPhase(battery);
    const skipReason = getSkipReason(battery);
    const maxAssignablePower = skipReason === null
        ? (isCharging ? chargingLimiter(battery.soc, battery.charging_max) : Math.max(0, Number(battery.discharging_max) || 0))
        : 0;
    const assignablePower = skipReason === null && isCharging && typeof phaseAllocator.getResponsivePowerLimit === "function"
        ? phaseAllocator.getResponsivePowerLimit(battery, maxAssignablePower, "charge")
        : maxAssignablePower;

    phaseAssignablePower[phase] += Number(assignablePower);

    return {
        battery,
        phase,
        skipReason,
        assignablePower,
        assignedPower: 0,
    };
});

batteries_total_assignable_power = Object.entries(phaseAssignablePower).reduce((sum, [phase, power]) => {
    const phaseLimit = getPhaseCommandLimitValue(phase);
    return sum + Math.min(Number(power) || 0, phaseLimit);
}, 0);

function assignPowerFirstFit(state, requestedPower) {
    if (remaining_output_power <= 0 || requestedPower <= 0 || state.skipReason !== null) return 0;

    const remainingBatteryPower = Math.max(0, state.assignablePower - state.assignedPower);
    const phaseLimitPower = getPhaseCommandLimitRemaining(state.phase);
    const assignedPower = Math.min(requestedPower, remainingBatteryPower, remaining_output_power, phaseLimitPower);
    if (assignedPower <= 0) return 0;

    state.assignedPower += assignedPower;
    remaining_output_power -= assignedPower;
    usePhaseCommandLimit(state.phase, assignedPower);
    return assignedPower;
}

function assignPowerWithAllocator(candidateStates, requestedPower, allocator) {
    const requested = Math.max(0, Number(requestedPower) || 0);
    if (remaining_output_power <= 0 || requested <= 0) return { assigned: 0, unassigned: requested };

    const eligibleStates = candidateStates
        .filter((state) => state.skipReason === null)
        .map((state) => ({
            state,
            availablePower: Math.max(0, state.assignablePower - state.assignedPower),
        }))
        .filter((entry) => entry.availablePower > 0);

    if (eligibleStates.length === 0) return { assigned: 0, unassigned: requested };

    const statesByPhase = eligibleStates.reduce((groups, entry) => {
        if (!groups[entry.state.phase]) groups[entry.state.phase] = [];
        groups[entry.state.phase].push(entry);
        return groups;
    }, {});

    const phaseGroups = Object.entries(statesByPhase)
        .map(([phase, entries]) => {
            const batteryCapacity = entries.reduce((sum, entry) => sum + entry.availablePower, 0);
            const phaseCapacity = Math.min(batteryCapacity, getPhaseCommandLimitRemaining(phase));
            return { phase, entries, capacity: phaseCapacity };
        })
        .filter((group) => group.capacity > 0);

    if (phaseGroups.length === 0) return { assigned: 0, unassigned: requested };

    const targetPower = Math.min(requested, remaining_output_power);
    const phaseAllocations = allocator(phaseGroups, targetPower, (group) => group.capacity);
    let assignedTotal = 0;

    phaseGroups.forEach((group) => {
        const phaseAssignedPower = phaseAllocations.get(group) || 0;
        if (phaseAssignedPower <= 0) return;

        const batteryAllocations = allocator(group.entries, phaseAssignedPower, (entry) => entry.availablePower);
        let assignedOnPhase = 0;

        group.entries.forEach((entry) => {
            const assignedPower = batteryAllocations.get(entry) || 0;
            if (assignedPower <= 0) return;

            entry.state.assignedPower += assignedPower;
            assignedOnPhase += assignedPower;
            assignedTotal += assignedPower;
        });

        usePhaseCommandLimit(group.phase, assignedOnPhase);
    });

    remaining_output_power -= assignedTotal;
    return { assigned: assignedTotal, unassigned: Math.max(0, requested - assignedTotal) };
}

// Fair share within a phase. Only used when a phase-protection requirement has to be
// split between the batteries that sit on the constrained phase.
function assignPowerBalanced(candidateStates, requestedPower) {
    const requested = Math.max(0, Number(requestedPower) || 0);

    if (usePhasePriorityFirst) {
        return assignPowerWithAllocator(candidateStates, requested, phaseAllocator.allocatePriorityWaterFill);
    }
    if (usePhaseWaterFill) {
        return assignPowerWithAllocator(candidateStates, requested, phaseAllocator.allocateWaterFill);
    }

    return assignPowerConcentrated(candidateStates, requested);
}

// Concentrate the load on as few inverters as possible. Inverters are inefficient at a
// fraction of their rating, so fill batteries in priority order instead of spreading a
// small demand thinly across every phase. Per-phase command limits are still honoured,
// because assignPowerFirstFit() clamps to the phase's remaining allowance.
function assignPowerConcentrated(candidateStates, requestedPower) {
    const requested = Math.max(0, Number(requestedPower) || 0);

    let assigned = 0;
    candidateStates.forEach((state) => {
        assigned += assignPowerFirstFit(state, requested - assigned);
    });

    return { assigned, unassigned: Math.max(0, requested - assigned) };
}

// Phase-specific assignment first. This prevents a phase-protection request from
// being consumed by batteries on a phase that cannot correct the violation.
if (phaseProtectionActive && phaseDirectionMatches) {
    PHASES.forEach((phase) => {
        const phaseRequiredPower = Math.max(0, Math.round(Number(phaseRequirements[phase]) || 0));
        phaseAssignment[phase].required = phaseRequiredPower;

        if (phaseRequiredPower <= 0) return;

        log(this, `Phase protection ${phase}: assigning ${phaseRequiredPower} W`);
        const allocation = assignPowerBalanced(
            batteryStates.filter((state) => state.phase === phase),
            phaseRequiredPower
        );

        phaseAssignment[phase].assigned += allocation.assigned;
        phaseAssignment[phase].unassigned = allocation.unassigned;
        if (allocation.unassigned > 0) {
            log(this, `Phase protection ${phase}: ${allocation.unassigned} W could not be assigned to batteries on this phase`, "warn");
        }
    });
}

// Aggregate residual assignment second. During phase protection this is only the
// part of the requested output that is not already reserved for phase correction.
let aggregatePowerToAssign = phaseProtectionActive && phaseDirectionMatches
    ? Math.min(phaseAggregateResidual, remaining_output_power)
    : remaining_output_power;

const aggregateAllocation = assignPowerConcentrated(batteryStates, aggregatePowerToAssign);
aggregateAssignedPower += aggregateAllocation.assigned;

// Build solutions after all phase and aggregate assignments are known.
const solution_array = batteryStates.map((state) => {
    if (state.skipReason !== null) {
        log(this, state.skipReason);
        return getStopSolution(state.battery.id);
    }

    let solution;
    if (state.assignedPower <= 0) {
        solution = getStopSolution(state.battery.id);
    } else {
        solution = getActiveSolution(state.battery.id, state.assignedPower);
    }

    // Explain: charge limiting
    if(isCharging && state.assignablePower < state.battery.charging_max) {
        log(this,`Charging limited to protect battery (${state.battery.soc}%): ${state.battery.charging_max}W -> ${state.assignablePower}W`);
    }
    // Explain: solution result
    log(this, `<font color="#009ac7">Battery ${solution.id}</font>: assigned to ${solution.mode} with ${solution.power}W / ${isCharging ? state.battery.charging_max : state.battery.discharging_max }W max.`)

    return solution;
});

// battery discharge priority - put solutions back in initial order
if (!isCharging && hasReverseDischargePriority) {
    solution_array.reverse();
    batteries.reverse();
}

const assignedTotalPower = batteryStates.reduce((sum, state) => sum + Math.max(0, Number(state.assignedPower) || 0), 0);
const unassignedPower = Math.max(0, unassigned_power_initial - assignedTotalPower);

if (phaseProtectionActive && phaseDirectionMatches) {
    RED.util.setMessageProperty(msg, "phase_protection.assignment", {
        by_phase: phaseAssignment,
        aggregate_assigned_power: Math.round(aggregateAssignedPower),
    }, true);
}

// store solutions in msg
RED.util.setMessageProperty(msg, "solutions", solution_array,true);
// store remaining load distribution results and PID_OUPUT in msg
RED.util.setMessageProperty(msg, "pid.output", unassigned_power_initial, true); // the dampenend & filtered PID_output equals the load requirement
RED.util.setMessageProperty(msg, "pid.load", unassigned_power_initial, true);
RED.util.setMessageProperty(msg, "pid.load_capacity", batteries_total_assignable_power, true);
RED.util.setMessageProperty(msg, "pid.load_assigned", parseInt(assignedTotalPower), true);
RED.util.setMessageProperty(msg, "pid.load_unassigned", unassignedPower,true);

// OUTFLOW
flow.set("batteries_total_assignable_power", batteries_total_assignable_power); // this is set for the anti-windup calculation in the earlier 'calculate corrections' node, which will pick this up during next iteration.

// OUTPUT
return msg; // to Home Battery flow

