}

// Logger, usage: log(this, "");
const log = global.get('logger');
log(this, "Discharge at **max. power**");

// INPUT
const batteries = Array.isArray(msg.batteries) ? msg.batteries : [];
const limitsAvailable = RED.util.getMessageProperty(msg, "phase_protection.command_limits_available") === true;
const phaseDischargeLimits = limitsAvailable
    ? (RED.util.getMessageProperty(msg, "phase_protection.command_limit_by_phase.discharge") || {})
    : {};
const phaseAllocator = global.get("phasePowerAllocator");

function buildFirstFitStates() {
    const PHASES = ["L1", "L2", "L3"];
    const phaseRemaining = { ...phaseDischargeLimits };
    const getPhase = (battery) => {
        const phase = String(battery.phase || "").toUpperCase();
        return PHASES.includes(phase) ? phase : "unassigned";
    };

    return batteries.map((battery) => {
        const phase = getPhase(battery);
        const requestedPower = Math.max(0, Number(battery.discharging_max) || 0);
        const remaining = Number(phaseRemaining[phase]);
        const assignedPower = PHASES.includes(phase) && Number.isFinite(remaining)
            ? Math.min(requestedPower, Math.max(0, remaining))
            : requestedPower;

        if (PHASES.includes(phase) && Number.isFinite(remaining)) {
            phaseRemaining[phase] = Math.max(0, remaining - assignedPower);
        }

        return { battery, phase, requestedPower, assignedPower };
    });
}

const batteryStates = typeof phaseAllocator?.buildMaxPowerStates === "function"
    ? phaseAllocator.buildMaxPowerStates({ batteries, maxPowerProperty: "discharging_max", phaseLimits: phaseDischargeLimits })
    : buildFirstFitStates();

// build solution
const solution_array = batteryStates.map((state) => {
    if (state.assignedPower < state.requestedPower) {
        log(this, `Battery ${state.battery.id}: phase ${state.phase} discharge limit ${state.requestedPower}W -> ${state.assignedPower}W`);
    }

    return {
        id: state.battery.id,
        mode: state.assignedPower > 0 ? "discharge" : "stop",
        power: Math.round(state.assignedPower)
    };
});

// return solution
msg.solutions = solution_array;
return msg;

