msg.batteries.forEach(battery => {
    // Skip batteries that did not report: one missing reading would otherwise turn the
    // whole reserve into NaN, or silently count as 0 kWh once normalized to null.
    if (!isReading(battery.energy_max) || !isReading(battery.soc_max) || !isReading(battery.soc_min)) return;
    max_reserve += (battery.energy_max*battery.soc_max - battery.energy_max*battery.soc_min)/100; // kWh
});
output = Math.min(output, max_reserve);

